"use client";
import { useState } from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Trash2, Edit3, Check, X, AlertCircle } from "lucide-react";

export default function TaskItem({ id, text }: any) {
  const [isEditing, setIsEditing] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [newTitle, setNewTitle] = useState(text);

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ 
    id, disabled: isEditing || isDeleting 
  });

  const style = { 
    transform: CSS.Transform.toString(transform), 
    transition, 
    opacity: isDragging ? 0.3 : 1,
    scale: isDragging ? "1.05" : "1",
  };

  const handleUpdate = async () => {
    if (!newTitle.trim() || newTitle === text) return setIsEditing(false);
    const res = await fetch("/api/scrumboard/items", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: text, newTitle: newTitle }),
    });
    if (res.ok) window.location.reload();
  };

  const handleDelete = async () => {
    const res = await fetch("/api/scrumboard/items", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: text }),
    });
    if (res.ok) window.location.reload();
  };

  return (
    <div 
      ref={setNodeRef} style={style} 
      className={`group p-5 rounded-2xl border transition-all duration-300 ${
        isDeleting ? "bg-red-500/10 border-red-500/50" : "bg-[#1A1D29] border-white/5 hover:border-blue-500/30 hover:shadow-2xl hover:shadow-blue-500/5"
      }`}
    >
      {isEditing ? (
        <div className="flex flex-col gap-3">
          <input className="bg-black/40 border border-white/10 rounded-xl p-3 text-white text-xs outline-none focus:border-blue-500" value={newTitle} onChange={e => setNewTitle(e.target.value)} autoFocus />
          <div className="flex justify-end gap-2">
            <button onClick={() => setIsEditing(false)} className="text-slate-500 p-1 hover:text-white"><X size={16}/></button>
            <button onClick={handleUpdate} className="text-green-500 p-1 hover:text-green-400"><Check size={16}/></button>
          </div>
        </div>
      ) : isDeleting ? (
        <div className="flex items-center justify-between animate-in zoom-in duration-200">
          <div className="flex items-center gap-2 text-red-500 text-[10px] font-black uppercase tracking-tighter">
            <AlertCircle size={14} /> <span>Verwijderen?</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDeleting(false)} className="bg-white/5 text-slate-300 px-3 py-1 rounded-lg text-[10px] font-bold">Nee</button>
            <button onClick={handleDelete} className="bg-red-600 text-white px-3 py-1 rounded-lg text-[10px] font-bold shadow-lg shadow-red-600/20">Ja</button>
          </div>
        </div>
      ) : (
        <div className="flex justify-between items-start gap-3">
          <div {...attributes} {...listeners} className="flex-1 cursor-grab active:cursor-grabbing text-xs text-slate-300 leading-relaxed font-medium">
            {text}
          </div>
          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => setIsEditing(true)} className="text-slate-600 hover:text-blue-400"><Edit3 size={14} /></button>
            <button onClick={() => setIsDeleting(true)} className="text-slate-600 hover:text-red-400"><Trash2 size={14} /></button>
          </div>
        </div>
      )}
    </div>
  );
}